   "section": "5.1",
   "cuts": [80, 84],
   "paragraphs": [
    {"start": 80, "end": 83, "ending": "引出看约伯的永久安稳人生，并追问什么叫永久安稳的人生", "title": "引出约伯记1章1至5节，邀请读者看约伯近乎永久安稳的人生，并追问什么叫永久安稳的人生"},
    {"start": 84, "end": 88, "ending": "进入经文，乌斯地有一个人名叫约伯", "title": "介绍背景：约伯记被认为是最早写成的一卷书，比创世记还早，约伯生活在很早的年代，可能比亚伯拉罕更早；随后进入经文，乌斯地有一个人名叫约伯"}
   ],
   "uncertain": []
  },
  {
   "section": "5.2",
   "cuts": [89, 94, 99, 106],
   "paragraphs": [
    {"start": 89, "end": 93, "ending": "约伯可能比亚伯拉罕更早，是认识独一真神的古代圣徒", "title": "约伯是乌斯地人，并非以色列人；他可能生活在族长时代之前、比亚伯拉罕更早，是认识独一真神的古代圣徒"},
    {"start": 94, "end": 98, "ending": "耶和华是全地的主，全人类的主", "title": "针对「旧约只有以色列人信上帝」的误会，指出并非如此，耶和华是全地的主、全人类的主，不是以色列人发明了耶和华"},
    {"start": 99, "end": 105, "ending": "巴兰虽是行邪术的，也知道耶和华的名字", "title": "举例说明亚伯拉罕之前已有人信耶和华：亚伯拉罕认识至高祭司、撒冷王麦基洗德，并向他纳十分之一；以东行邪术的巴兰也知道耶和华的名字"},
    {"start": 106, "end": 114, "ending": "早在约伯年代，至少乌斯地有一个非常敬畏上帝的人，就是约伯", "title": "独一神信仰不是从摩西才开始，该隐也认识耶和华；万族都知道耶和华，只是纯正信仰后来在一族人中被保全；早在约伯的年代，乌斯地已有一个非常敬畏上帝的人"}
   ],
   "uncertain": []
  },
  {
   "section": "5.3",
   "cuts": [115, 121, 129, 133, 141],
   "paragraphs": [
    {"start": 115, "end": 120, "ending": "追问为什么约伯记开篇要写1到5节，强调圣经没有一段细节是枉费的", "title": "追问圣经为何收录约伯的故事、约伯记1章开篇为何要写1至5节，强调圣经没有一段细节是枉费白费的"},
    {"start": 121, "end": 128, "ending": "通常认为钱多、人多、资源多的人家，遇事更能平事", "title": "提问约伯记开篇要读者先明白什么，并以一般人的眼光设想：什么样的人、什么样的家庭绝不会出意外，通常认为是钱多、人多、资源多，遇事更能平事"},
    {"start": 129, "end": 132, "ending": "按各时代眼光，约伯是不会遭灾祸、能面对任何风险的", "title": "从描述看，作者突出约伯身上一个鲜明的特点，就是他和家庭的稳，按各个时代的眼光，他都是不会遭遇灾祸、能面对任何风险的人"},
    {"start": 133, "end": 140, "ending": "1至5节的平安稳妥与大灾难中的不安稳形成极大落差", "title": "解释约伯记1章1至5节先交代约伯的稳，是因为他后面落到极大的灾难中，前面的绝对平安稳妥与后面的完全不安稳形成极大的落差"},
    {"start": 141, "end": 144, "ending": "许多老弟兄老姐妹也知道约伯后来家破人亡、浑身疾病、躺在炉灰中", "title": "指出读者可以用这个落差慢慢思考自己对耶和华信心的根基；许多老弟兄老姐妹即使没特别读懂约伯记，也知道约伯后来家破人亡、浑身疾病、躺在炉灰中"}
   ],
   "uncertain": [
    {"line": 121, "reason": "121 是提出问题、为下文 122 的设问开口，按过渡句归属规则归后"}
   ]
  },
  {
   "section": "5.4",
   "cuts": [145, 150, 154, 169],
   "paragraphs": [
    {"start": 145, "end": 149, "ending": "知道太多反而破坏开头应有的思路", "title": "提醒读约伯记1章1至5节时先不管后面的故事，不要带着「上帝视角」，因为知道太多反而会破坏读开头时应有的思路"},
    {"start": 150, "end": 153, "ending": "会认为约伯这样的家庭应该不会出现变故", "title": "设想只看约伯记1章1至5节，如果在生活中遇到约伯这样的人，会不会认为他的家庭会出现变故，答案应该是不会"},
    {"start": 154, "end": 168, "ending": "抗风险能力最强的人通常被认为最平安，人都有对生活不安稳的担忧", "title": "列举人生动荡的风险因素：努力赚钱、锻炼身体、购买保险都是为了增加家庭的抗风险能力；抗风险能力最强的人通常被认为最平安，人都有对生活不安稳的担忧和风险意识"},
    {"start": 169, "end": 174, "ending": "家庭易遭灾或因抗风险低，或为恶人常在恶事里被反噬", "title": "讲一般人对突然遭灾者的看法，即恶有恶报：一个家庭容易遭灾，可能因为抗风险能力低，也可能因为他是恶人、常在恶事里被反噬，所谓常在河边走难免不湿鞋"}
   ],
   "uncertain": []
  },
  {
   "section": "5.5",
   "cuts": [175, 185, 190, 196, 206, 212],
   "paragraphs": [
    {"start": 175, "end": 184, "ending": "约伯完全正直、远离恶事，排除道德和违法犯罪的风险", "title": "约伯不是坏人；圣经首先给出他第一个稳健因素，即完全正直、远离恶事，也就是把他身上任何道德和违法犯罪所带来的风险彻底排除"},
    {"start": 185, "end": 189, "ending": "作奸犯科的家庭会招灾，但约伯没有这些", "title": "假设一个家庭作奸犯科、开赌场贩毒，人们会认为它迟早遭殃，因为身处恶势力、没有远离恶事又不正直，会招来灾祸；而约伯不是这样"},
    {"start": 190, "end": 195, "ending": "约伯敬畏神，连属灵遭天谴的因素也排开，且被耶和华承认", "title": "约伯完全正直、敬畏神、远离恶事；敬畏神这一点连耶和华都承认，说明他连属灵的、遭天谴的因素也排除了"},
    {"start": 196, "end": 205, "ending": "基于错误信仰，可能因上帝愤怒遭家庭牵连，这是第二个不稳健因素", "title": "设想一个没干违法犯罪之事的好人，还可能因不信上帝、拜偶像、乱搞迷信、信仰上污秽而遭上帝愤怒的牵连，这是基于错误信仰的第二个不稳健因素"},
    {"start": 206, "end": 211, "ending": "约伯各方面风险因素都不存在，敬畏且被上帝认可", "title": "约伯敬畏神、远离恶事、完全正直、生活上没有违法乱纪，因此从道德伦理、司法到信仰虔诚度的一切风险因素在他身上都不存在，他的敬畏且被上帝认可"},
    {"start": 212, "end": 215, "ending": "这样的家庭若还遇波折，还有什么可能因素", "title": "由约伯记1章1节可以认同约伯是好人、好弟兄、好虔诚人；但这样的家庭若还会遇到波折，那还有什么可能性的因素"}
   ],
   "uncertain": []
